// ---- diagnosis --------------------------------------------------------------

// diagnose reads a round. failure is a state that ends the wait at once;
// pending is a state that does (when it lasts) but may also be passing.
func diagnose(p Params, obs observation) (failure, pending *BenchError) {
	for _, pod := range obs.pods {
		if pod.Metadata.DeletionTimestamp != nil {
			continue
		}
		if f := podFailure(p, pod); f != nil {
			return f, nil
		}
	}
	return nil, pendingReading(p, obs)
}

// podFailure is a pull that fails or a container that crashes.
func podFailure(p Params, pod podObject) *BenchError {
	for _, cs := range pod.Status.ContainerStatuses {
		waiting := ""
		if cs.State.Waiting != nil {
			waiting = cs.State.Waiting.Reason
		}
		last := ""
		switch {
		case cs.LastState.Terminated != nil:
			last = cs.LastState.Terminated.Reason
		case cs.State.Terminated != nil:
			last = cs.State.Terminated.Reason
		}
		switch {
		case waiting == reasonErrImagePull || waiting == reasonImagePullBackOff:
			return &BenchError{
				Kind:  ImagePull,
				Cause: fmt.Sprintf("the image %s could not be pulled (%s)", p.ImageRef(), waiting),
				Check: describePodCommand(p) + ", then check " + envImage + ", " + envImageTag + " and the access of the cluster to the registry",
			}
		case waiting == reasonCrashLoop || last == reasonOOMKilled:
			return crashFailure(p, waiting, last)
		}
	}
	return nil
}

func crashFailure(p Params, waiting, last string) *BenchError {
	state := "restarted"
	if waiting != "" {
		state = waiting
	}
	if last == "" {
		last = "unknown"
	}
	return &BenchError{
		Kind:  Crash,
		Cause: fmt.Sprintf("the Nexus container keeps crashing (%s, last termination: %s) with a memory limit of %s", state, last, p.MemoryLimit),
		Check: describePodCommand(p) + " and `kubectl --context " + p.Context + " -n " + p.Namespace + " logs deploy/nexus --previous`; raise " + envMemoryLimit + " when it was " + reasonOOMKilled,
	}
}

// pendingReading is a pod that cannot be scheduled, or a claim that stays
// Pending although a pod is scheduled. The pod comes first: while it is not
// scheduled, a claim of a WaitForFirstConsumer class is Pending for that reason
// alone.
func pendingReading(p Params, obs observation) *BenchError {
	scheduled := false
	for _, pod := range obs.pods {
		if pod.Metadata.DeletionTimestamp != nil {
			continue
		}
		if msg, ok := pod.unschedulable(); ok {
			return unschedulableReading(p, msg)
		}
		scheduled = scheduled || pod.scheduled()
	}
	if scheduled && obs.pvc != nil && obs.pvc.Status.Phase == "Pending" {
		return &BenchError{
			Kind:  PodPending,
			Cause: fmt.Sprintf("the volume claim %s (%s of storage) is still Pending although the pod is scheduled", obs.pvc.Metadata.Name, p.StorageSize),
			Check: kubectlIn(p, "describe", "pvc", obs.pvc.Metadata.Name) + ", then lower " + envStorageSize + " or check the default StorageClass",
		}
	}
	return nil
}

// testOpName names the operations in sub-test titles and messages.
var testOpName = map[Op]string{OpUp: "up", OpProvision: "provision", OpDown: "down", OpStatus: "status"}

// requiredCheck is a can-i the preflight must ask for an operation.
type requiredCheck struct {
	verb, resource string
	scope          string // "namespace" (-n <ns>), "cluster" (no -A) or "all" (-A)
}

// requiredChecks is the list of F2 the plan fixes. The fake answers "yes" to any
// other can-i, so the code may ask for more; it may not ask for less.
var requiredChecks = map[Op][]requiredCheck{
	OpUp: {
		{"create", "namespaces", "cluster"},
		{"create", "persistentvolumeclaims", "namespace"},
		{"create", "services", "namespace"},
		{"create", "deployments", "namespace"},
		{"create", "secrets", "namespace"},
		{"create", "pods/exec", "namespace"},
		{"list", "services", "all"},
		// Server-side apply is a PATCH, also on a second run; Deploy reads the
		// pods and the claims of the namespace while it waits.
		{"patch", "deployments", "namespace"},
		{"patch", "services", "namespace"},
		{"patch", "persistentvolumeclaims", "namespace"},
		{"get", "pods", "namespace"},
		{"list", "pods", "namespace"},
		{"get", "persistentvolumeclaims", "namespace"},
		{"list", "persistentvolumeclaims", "namespace"},
	},
	OpProvision: {{"create", "pods/exec", "namespace"}},
	OpDown:      {{"delete", "namespaces", "cluster"}},
}

func (c requiredCheck) matches(q canIQuery, p Params) bool {
	if q.verb != c.verb || q.resource != c.resource {
		return false
	}
	switch c.scope {
	case "namespace":
		return q.namespace == p.Namespace && !q.allNamespaces
	case "all":
		return q.allNamespaces
	default:
		return !q.allNamespaces
	}
}

func TestWriteVerbDetector(t *testing.T) {
	tests := []struct {
		args  []string
		write bool
	}{
		{[]string{"apply", "--server-side", "-f", "-"}, true},
		{[]string{"create", "namespace", "x"}, true},
			name: "get namespace fails in a way nobody planned, and the stderr holds a secret",
			op:   OpUp,
			setup: func(f *fakeKubectl) {
				f.nsReply = &fakeReply{
					stderr: "Error from server (InternalError): Internal error occurred: token=" + fakeSecret + " rejected\n",
					err:    errFakeExit1,
				}
			},
			unplanned: true,
		},
	}
	// Every verb and resource of the required list, denied one at a time.
	for _, op := range []Op{OpUp, OpProvision, OpDown} {
		for _, c := range requiredChecks[op] {
			cases = append(cases, failCase{
				name: "can-i says no to " + c.verb + " " + c.resource + " (" + testOpName[op] + ")",
				op:   op,
				setup: func(f *fakeKubectl) {
					// The namespace is there for provision and down, so that the
					// order of the checks does not matter to the outcome.
					if op != OpUp {
						f.ours()
					}
					f.deny(c.verb, c.resource)
				},
				kind:    Forbidden,
				mention: []string{c.verb, c.resource},
			})
		}
	}
	return cases
}

func TestRunPreflightFails(t *testing.T) {
	for _, tt := range failCases() {
