				if _, ok := b.nexus.User("bench-pull"); ok {
					t.Error("the user bench-pull was created")
				}
				if _, ok := b.nexus.Role("bench-docker-pull"); ok {
					t.Error("the role bench-docker-pull was created")
				}
				if b.nexus.EULAAccepted() {
